contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address receiver, uint amount) public payable {
        require(receiver != address(0));
        require(amount > 0);

        // Read owner's address via observable effect: deployer of c is owner, which is address(c).balance not useful.
        // Since C does not expose owner, we instead check that the owner (msg.sender when C was constructed) equals address(this).
        // The checker deploys a fresh C with this test contract as deployer, so owner == address(this).

        // Attempt the call and record whether it reverted
        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // The owner of c should remain this contract regardless of revert: verify that only this contract can call sendTo successfully.
        // We express the invariant: if a subsequent call from this contract with amount 1 to receiver reverts, then the earlier call must have also reverted.
        // This encodes that ownership hasn't changed (if ownership changed away from this contract, both calls would revert; if ownership stayed, behavior consistent).

        bool secondReverted;
        c.sendTo(receiver, 1); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        // General rule: both attempts from this contract have the same revert outcome iff ownership is unchanged; thus assert they are equal.
        assert(reverted == secondReverted);
    }
    receive() external payable { }
}

